  if (bybitFrac !== null && Number.isFinite(bybitFrac)) return bybitFrac * 100;
  const lcPct = safeNum(d.percent_change_1h, null);
  if (lcPct !== null && Number.isFinite(lcPct)) return lcPct;
  const last = safeNum(d.lastPrice, null);
  const prev = safeNum(d.prevPrice1h, null);
  if (last && prev) return ((last - prev) / prev) * 100;
  return 0;
}

// === MAIN ===
try {
  const items = $input.all().map(i => i.json);
  if (!items || !items.length) return [];

  // Find BTC
  const btcData = items.find(
    (d) => (d.symbol || '').toUpperCase() === 'BTC' || (d.symbol || '').toUpperCase() === 'BTCUSDT'
  );

  // Universe stats for normalization
  const vols = items.map((d) => safeNum(d.volume24h, 0));
  const turns = items.map((d) => safeNum(d.turnover24h, 0));
  const oiVals = items.map((d) => safeNum(d.openInterestValue, 0));
  const inters = items.map((d) => safeNum(d.interactions_24h, 0));
  const socs = items.map((d) => safeNum(d.social_volume_24h, 0));

  const maxVol = Math.max(...vols, 1);
  const maxTurn = Math.max(...turns, 1);
  const maxOI = Math.max(...oiVals, 1);
  const maxSocial = Math.max(...socs, 1);

  // Hard filters
  const { volatilityMin, volatilityMax } = CONFIG.MIN_REQUIREMENTS;
  const passQualityGates = (d) => {
    const min = CONFIG.MIN_REQUIREMENTS;
    if (safeNum(d.volume24h, 0) < min.volume24h) return false;
    if (safeNum(d.turnover24h, 0) < min.turnover24h) return false;
    if (safeNum(d.openInterestValue, 0) < min.openInterestValue) return false;
    if (safeNum(d.social_volume_24h, 0) < min.social_volume_24h) return false;
    const v = safeNum(d.volatility, 0);
    if (v < volatilityMin || v > volatilityMax) return false;
    return true;
  };

  let candidates = items.filter(passQualityGates);
  if (candidates.length < CONFIG.TOP_K) {
    candidates = items.filter((d) => {
      const v = safeNum(d.volatility, 0);
      return (
        safeNum(d.volume24h, 0) > CONFIG.MIN_REQUIREMENTS.volume24h * 0.7 &&
        safeNum(d.turnover24h, 0) > CONFIG.MIN_REQUIREMENTS.turnover24h * 0.7 &&
        safeNum(d.openInterestValue, 0) > CONFIG.MIN_REQUIREMENTS.openInterestValue * 0.7 &&
        safeNum(d.social_volume_24h, 0) > CONFIG.MIN_REQUIREMENTS.social_volume_24h * 0.7 &&
        v > volatilityMin * 0.7 &&
        v < volatilityMax * 1.2
      );
    });
  }

  const W = CONFIG.WEIGHTS;
  const TH = CONFIG.THRESHOLDS;

  const scored = candidates.map((d) => {
    const symbol = d.symbol || '';
    const name = d.name || '';
    const price = safeNum(d.price, safeNum(d.lastPrice, 0));

    const vol24 = safeNum(d.volume24h, 0);
    const turn24 = safeNum(d.turnover24h, 0);
    const oiVal = safeNum(d.openInterestValue, 0);
    const fr = safeNum(d.fundingRate, 0);
    const volat = safeNum(d.volatility, 0);

    const pct1h = clamp(getPctChange1h(d), -50, 100);
    const pct24h = clamp(getPctChange24h(d), -80, 300);

    const interactions = safeNum(d.interactions_24h, 0);
    const socialVol = safeNum(d.social_volume_24h, 0);
    const galaxy = safeNum(d.galaxy_score, 0);
    const galaxyPrev = safeNum(d.galaxy_score_previous, galaxy);
    const altRank = safeNum(d.alt_rank, 9999);
    const altRankPrev = safeNum(d.alt_rank_previous, altRank);
    const sentiment = safeNum(d.sentiment, 50);
    const categories = toTags(d.categories);

    const oiRatio = turn24 > 0 ? oiVal / turn24 : 0;
    const engagementEfficiency = socialVol > 0 ? interactions / socialVol : 0;
    const galaxyJump = galaxy - galaxyPrev;
    const altRankJump = Math.max(0, altRankPrev - altRank);
    const fundingSkew = Math.abs(fr) < TH.fundingAbsSmall ? 0 : fr * (sentiment / 100);

    // Scores
    const liqScore =
      0.4 * norm01(vol24, 0, maxVol) +
      0.4 * norm01(turn24, 0, maxTurn) +
      0.2 * norm01(oiVal, 0, maxOI);

    const socialScore =
      0.5 * norm01(socialVol, 0, maxSocial) +
      0.3 * clamp(engagementEfficiency / TH.socialEfficiencyGood, 0, 1) +
      0.2 * (sentiment / 100);

    const rankScore =
      0.55 * clamp(altRankJump / TH.altRankJump, 0, 1) +
      0.45 * clamp(galaxyJump / TH.galaxyJump, 0, 1);

    const mm1 = clamp((pct1h + 50) / 100, 0, 1);
    const mm24 = clamp((pct24h + 50) / 100, 0, 1);
    const oiComp = clamp(oiRatio / TH.oiRatioGood, 0, 1);
    const frComp = clamp((fundingSkew + 0.02) / 0.04, 0, 1);

    const marketMomentum = 0.35 * mm24 + 0.25 * mm1 + 0.25 * oiComp + 0.15 * frComp;

    let catBonus = 0;
    for (const tag of categories) {
      if (CONFIG.CATEGORY_BONUS[tag]) catBonus = Math.max(catBonus, CONFIG.CATEGORY_BONUS[tag]);
    }

    const rawScore =
      W.liquidity * liqScore +
      W.socialMomentum * socialScore +
      W.rankJumps * rankScore +
      W.marketMomentum * marketMomentum +
      W.categoryBonus * catBonus;

    const volPenalty =
      volat > CONFIG.MIN_REQUIREMENTS.volatilityMax
        ? 0.85
        : volat < CONFIG.MIN_REQUIREMENTS.volatilityMin
        ? 0.9
        : 1.0;

    const finalScore = clamp(rawScore * volPenalty, 0, 1) * 100;

    // Tags & reasons
    const tags = [];
    const reasons = [];
    if (altRankJump >= TH.altRankJump) {
      tags.push('ALTRANK_IMPROVING');
      reasons.push(`AltRank ↑ by ${altRankJump}`);
    }
    if (galaxyJump >= TH.galaxyJump) {
      tags.push('GALAXY_IMPROVING');
      reasons.push(`Galaxy ↑ by ${galaxyJump.toFixed(1)}`);
    }
    if (engagementEfficiency >= TH.socialEfficiencyGood) {
      tags.push('HIGH_ENGAGEMENT');
      reasons.push(`Engagement eff. ${engagementEfficiency.toFixed(1)}`);
    }
    if (oiRatio >= TH.oiRatioGood) {
      tags.push('LEVERAGED_INTEREST');
      reasons.push(`OI/Turnover ${oiRatio.toFixed(2)}`);
    }
    if (sentiment >= 70) {
      tags.push('BULLISH_SENTIMENT');
      reasons.push(`Sentiment ${sentiment}`);
    }
    if (pct24h >= 2) {
      tags.push('PRICE_MOMENTUM_24H');
      reasons.push(`24h ${pct24h.toFixed(2)}%`);
    }
    if (volat >= CONFIG.MIN_REQUIREMENTS.volatilityMin && volat <= CONFIG.MIN_REQUIREMENTS.volatilityMax) {
      tags.push('TRADEABLE_VOL');
      reasons.push(`Volatility ${volat.toFixed(4)}`);
    }

    const tier = finalScore >= 75 ? 'A' : finalScore >= 60 ? 'B' : 'C';

    // === OUTPUT ===
    return {
      symbol,
      name,
      price,
      logo: d.logo || null,
      network: d.blockchains?.[0]?.network || null,
      address: d.blockchains?.[0]?.address || null,
      category_main: categories[0] || null,
      score: parseFloat(finalScore.toFixed(2)),
      tier,
      tags,
      reasons,
      derived: {
        pct_change_1h: parseFloat(pct1h.toFixed(2)),
        pct_change_24h: parseFloat(pct24h.toFixed(2)),
        volatility: parseFloat(volat.toFixed(5)),
        oi_ratio: parseFloat(oiRatio.toFixed(3)),
        engagement_efficiency: parseFloat(engagementEfficiency.toFixed(2)),
        galaxy: parseFloat(galaxy.toFixed(2)),
        galaxy_prev: parseFloat(galaxyPrev.toFixed(2)),
        galaxy_jump: parseFloat(galaxyJump.toFixed(2)),
        alt_rank: altRank,
        alt_rank_prev: altRankPrev,
        alt_rank_jump: altRankJump,
        sentiment,
        volume24h: vol24,
        turnover24h: turn24,
        openInterestValue: oiVal,
        fundingRate: fr,
        market_cap: safeNum(d.market_cap, 0),
        market_cap_rank: safeNum(d.market_cap_rank, 0),
        circulating_supply: safeNum(d.circulating_supply, 0),
        max_supply: safeNum(d.max_supply, 0),
        social_dominance: safeNum(d.social_dominance, 0),
        market_dominance: safeNum(d.market_dominance, 0)
      },
      raw: {
        symbol: d.symbol,
        bybit_symbol: (d.symbol || '') + 'USDT',
        lastPrice: d.lastPrice,
        price24hPcnt: d.price24hPcnt,
        percent_change_1h: d.percent_change_1h,
        percent_change_24h: d.percent_change_24h,
        interactions_24h: d.interactions_24h,
        social_volume_24h: d.social_volume_24h,
        galaxy_score: d.galaxy_score,
        galaxy_score_previous: d.galaxy_score_previous,
        alt_rank: d.alt_rank,
        alt_rank_previous: d.alt_rank_previous,
        volatility: d.volatility,
        categories: d.categories,
        topic: d.topic,
        logo: d.logo,
        blockchains: d.blockchains,
        highPrice24h: d.highPrice24h,
        lowPrice24h: d.lowPrice24h,
        indexPrice: d.indexPrice,
        markPrice: d.markPrice,
        bid1Price: d.bid1Price,
        ask1Price: d.ask1Price,
        market_cap_rank: d.market_cap_rank
      }
    };
  });

  // Sort and select Top K
  scored.sort((a, b) => b.score - a.score);
  let top = scored.slice(0, CONFIG.TOP_K);

  // Ensure BTC first
  let finalList = [];
  if (CONFIG.INCLUDE_BTC && btcData) {
    const btcInTop = top.find(
      (x) => x.symbol.toUpperCase() === 'BTC' || x.symbol.toUpperCase() === 'BTCUSDT'
    );
    if (btcInTop) {
      const filtered = top.filter(
        (x) => x.symbol.toUpperCase() !== 'BTC' && x.symbol.toUpperCase() !== 'BTCUSDT'
      );
      finalList = [btcInTop, ...filtered];
    } else {
      const btcItem = {
        symbol: 'BTC',
        name: 'Bitcoin',
        price: safeNum(btcData.price, safeNum(btcData.lastPrice, 0)),
        logo: btcData.logo || null,
        score: 0,
        tier: 'BENCHMARK',
        tags: ['MARKET_LEADER'],
        reasons: ['BTC for regime analysis'],
        derived: {
          pct_change_1h: getPctChange1h(btcData),
          pct_change_24h: getPctChange24h(btcData),
          volatility: safeNum(btcData.volatility, 0),
          volume24h: safeNum(btcData.volume24h, 0),
          turnover24h: safeNum(btcData.turnover24h, 0),
          openInterestValue: safeNum(btcData.openInterestValue, 0),
          fundingRate: safeNum(btcData.fundingRate, 0),
          sentiment: safeNum(btcData.sentiment, 50)
        },
        raw: {
          symbol: 'BTC',
          bybit_symbol: 'BTCUSDT',
          lastPrice: btcData.lastPrice,
          price24hPcnt: btcData.price24hPcnt,
          logo: btcData.logo || null
        }
      };
      finalList = [btcItem, ...top];
    }
  } else {
    finalList = top;
  }

  return finalList.map((x) => ({ json: x }));

} catch (err) {
  return [
    {
      json: {
        error: 'ADAPTIVE_ENGINE_FAILED',
        message: err.message
      }
    }
  ];
}

