    return [{
        json: {
            message: "ERROR",
            reason: "No input from previous node",
            timestamp: new Date().toISOString()
        }
    }];
}

const lastItem = input[input.length - 1].json;

console.log('═'.repeat(80));
console.log('🧹 TRADE CLEANER v7.0 - Trade Runner Final');
console.log('═'.repeat(80));

// ═══════════════════════════════════════════════════════════════════════════════
