        rr: lastItem.rr,
        score: lastItem.action_score || lastItem.trade_score,
        liquidation_price: lastItem.liquidation_price
    }
};

console.log('\n[Trade Runner Request] Created:');
console.log(JSON.stringify(tradeRunnerRequest, null, 2));

