/**
 * NODE: Public Free Formatter v2.0
 * - Removes zero/empty fields
 * - Keeps only general + teaser fields
 * - Prepares web-safe JSON for public site
 */

function safeNum(v, d = 0) {
  const n = typeof v === 'string' ? parseFloat(v) : v;
  return Number.isFinite(n) ? n : d;
}

function cleanObject(obj) {
  const result = {};
  for (const [k, v] of Object.entries(obj)) {
    if (
      v === null ||
      v === undefined ||
      v === "" ||
      v === "N/A" ||
      (typeof v === "number" && v === 0)
    ) continue;
    result[k] = v;
  }
  return result;
}

const input = $input.all().map(i => i.json);
const free = [];

for (const coin of input) {
  const ta4h = coin.ta_4h || {};
  const struct = ta4h.market_structure || {};
  const derived = coin.derived || {};

  const item = {
    symbol: coin.symbol,
    name: coin.name,
    logo: coin.logo || coin.raw?.logo || null,
    price: safeNum(coin.price),

    alpha_score: safeNum(coin.score),
    rating_tier: coin.tier || undefined,

    daily_momentum: safeNum(derived.pct_change_24h),
    volatility_index: safeNum(derived.volatility),
    trade_flow_24h: safeNum(derived.volume24h),
    investor_sentiment: safeNum(derived.sentiment),

    social_strength: safeNum(derived.galaxy),
    market_quality: safeNum(derived.alt_rank),

    trend_bias: ta4h.market_structure?.structure,
    momentum_state: ta4h.rsi_signal,
    key_support: struct.support,
    key_resistance: struct.resistance,

    sector: coin.category_main || coin.raw?.categories || "general",
    signals: coin.tags || [],

    // Premium hook
    advanced_metrics: false,
    premium_hint: "Unlock detailed analytics & pro trader signals"
  };

  free.push(cleanObject(item));
}

// Sort by alpha_score descending
free.sort((a, b) => (b.alpha_score || 0) - (a.alpha_score || 0));

// Limit to 20 strongest coins
const result = free.slice(0, 20);

return result.map(x => ({ json: x }));
